.article-body {
  text-align: justify;
  hyphens: auto; /* Enable automatic hyphenation */
  -webkit-hyphens: auto; /* For WebKit browsers like Safari and Chrome */
  -ms-hyphens: auto;     /* For IE/Edge, though modern Edge uses WebKit prefix */

  /* Optional: Fine-tune hyphenation behavior */
  hyphenate-limit-chars: 6 3 2; /* min-chars-before-hyphen, min-chars-after-hyphen, min-word-length */
  hyphenate-limit-lines: 2; /* Max consecutive hyphenated lines */
}

/* CRITICAL: Ensure language is set for best hyphenation results */
html {
  lang: "en"; /* Or "de", "fr", etc., for accurate language-specific rules */
}
